  "lokal.zeiten_kurz.teil": "evenings/weekends only",
  "phasen.beifahrer.ausweis.cop": "I need ID from the passenger too.",
  "phasen.beifahrer.ausweis.nicht": "Don't give a false name – false personal details are a regulatory offence.",
  "phasen.beifahrer.ausweis.tipp": "If the officer insists: give your personal details under objection.",
  "phasen.beifahrer.durchsuchung.cop": "Empty your pockets, please.",
  "phasen.beifahrer.durchsuchung.nicht": "Don't empty your pockets yourself – that can look like consent.",
  "phasen.beifahrer.durchsuchung.tipp": "Keep your hands visible, don't hold onto anything, don't obstruct.",
  "phasen.beifahrer.ende.cop": "Wait here.",
  "phasen.beifahrer.ende.nicht": "Don't just walk away while it's unclear whether the check is over.",
  "phasen.beifahrer.ende.tipp": "After the check, save the video with \"Save copy now\".",
  "phasen.beifahrer.fragen.cop": "Where were you two this evening?",
  "phasen.beifahrer.fragen.nicht": "Don't say anything about the driver, not even \"to help\".",
  "phasen.beifahrer.fragen.tipp": "As a witness, you don't have to testify to the police without a summons from the public prosecutor's office.",
  "phasen.beifahrer.massnahme.cop": "You're coming with us to the station now.",
  "phasen.beifahrer.massnahme.nicht": "Don't pull away or run – otherwise you also risk a criminal case for resistance.",
  "phasen.beifahrer.massnahme.tipp": "Station, photos, fingerprints: object with words, not with your body.",
  "phasen.beifahrer.start.cop": "Good day, police. We're checking the vehicle.",
  "phasen.beifahrer.start.nicht": "Don't reach into bags or a backpack without warning first.",
  "phasen.beifahrer.start.tipp": "Stay seated, hands visible, speak slowly.",
